"""Finite telemetry adapter for exact discovery, approval and decoding.

The pipeline mirrors the protocol:

* every predicate of a job is grounded into the NetNomos AST and projected with
  the supplied quantified projection, so that ``any``/``all`` predicates keep
  their window semantics;
* the training windows and the declared Cartesian universe are evaluated as
  dense vectors;
* every eligible inclusion-minimal disjunction is discovered together with its
  per-literal witnesses and its universe counterexample;
* the operator approval list selects the active theory, which is the only
  theory used while decoding;
* decoding answers count full universe windows, not distinct target values,
  and reports the next characters that still admit a complete extension.
"""
from __future__ import annotations

from typing import Any, Mapping, Sequence

import numpy as np

from netnomos.ast import BinaryTerm, Compare, Constant, FuncCall, SymbolRef
from netnomos.learners.exact import enumerate_clauses
from netnomos.projection import GroundedPredicate, SelectedConstant, project_quantified_family
from netnomos.specs import (
    Comparator,
    ConstantSelectorSpec,
    QuantifierTemplateSpec,
    VariableSelectorSpec,
)
from netnomos.theory import evaluate_formula_vectors

OPS = dict(eq='=', ne='!=', lt='<', le='<=', gt='>', ge='>=')
DIGITS = '0123456789'


class WindowSchema:
    """Field/grid layout of one job: cells, columns and projected predicates."""

    def __init__(self, job: Mapping[str, Any]):
        self.job = job
        self.fields = list(job['fields'])
        self.names = {field['name']: index for index, field in enumerate(self.fields)}
        self.nf = len(self.names)
        self.slots = int(job['slots'])
        self.columns = [f'cell_{index}' for index in range(self.slots * self.nf)]
        self.families = {
            field['name']: [
                self.columns[self.position([slot, field['name']])]
                for slot in range(self.slots)
            ]
            for field in self.fields
        }
        self.types = {field['name']: field['type'] for field in self.fields}

    def position(self, ref: Sequence[Any]) -> int:
        """Flat cell index of a ``[slot, field]`` reference."""
        return int(ref[0]) * self.nf + self.names[ref[1]]

    def term(self, term: Mapping[str, Any]):
        """Ground one protocol term into the NetNomos AST."""
        if 'const' in term:
            return Constant(term['const'])
        if 'sum' in term:
            return FuncCall(
                'sum',
                tuple(SymbolRef(self.columns[self.position(ref)]) for ref in term['sum']),
            )
        reference = SymbolRef(self.columns[self.position(term['ref'])])
        if 'scale' in term:
            return BinaryTerm('*', Constant(term['scale']), reference)
        return reference

    def predicates(self) -> list[GroundedPredicate]:
        """Ground every declared predicate, preserving input positions as ids."""
        result: list[GroundedPredicate] = []
        for index, predicate in enumerate(self.job['predicates']):
            operator = Comparator(OPS[predicate['op']])
            if predicate['kind'] == 'cmp':
                formula = Compare(operator.value, self.term(predicate['left']), self.term(predicate['right']))
                display = f"{predicate['kind']}:{index}"
            else:
                template = QuantifierTemplateSpec(
                    name='window',
                    quantifier='exists' if predicate['kind'] == 'any' else 'forall',
                    selector=VariableSelectorSpec(),
                    operators=[operator],
                    constant=ConstantSelectorSpec(mode='explicit', values=[predicate['value']]),
                )
                formula, display = project_quantified_family(
                    predicate['field'],
                    self.families[predicate['field']],
                    template,
                    operator,
                    SelectedConstant(predicate['value'], None),
                )
            result.append(GroundedPredicate(str(index), formula, display, 0.0, {'position': index}))
        return result


class Universe:
    """The declared Cartesian universe of windows in mixed-radix order."""

    def __init__(self, job: Mapping[str, Any]):
        self.fields = list(job['fields'])
        self.names = {field['name']: index for index, field in enumerate(self.fields)}
        self.nf = len(self.names)
        self.slots = int(job['slots'])
        self.cell_count = self.slots * self.nf
        self.cell_domains: list[list[int]] = []
        for _slot in range(self.slots):
            for field in self.fields:
                self.cell_domains.append(list(field['domain']))
        sizes = [len(domain) for domain in self.cell_domains]
        total = 1
        for size in sizes:
            total *= size
        self.size = total
        flat = np.arange(total, dtype=np.int64)
        self.values: list[np.ndarray] = [None] * self.cell_count
        self.positions: list[np.ndarray] = [None] * self.cell_count
        stride = 1
        for index in range(self.cell_count - 1, -1, -1):
            domain = np.asarray(self.cell_domains[index], dtype=np.int64)
            position = (flat // stride) % sizes[index]
            self.positions[index] = position
            self.values[index] = domain[position]
            stride *= sizes[index]

    def position(self, ref: Sequence[Any]) -> int:
        """Flat cell index of a ``[slot, field]`` reference."""
        return int(ref[0]) * self.nf + self.names[ref[1]]

    def field_domain(self, name: str) -> list[int]:
        """Declared domain of a field."""
        return list(self.fields[self.names[name]]['domain'])


def flatten_windows(job: Mapping[str, Any]) -> list[list[int]]:
    """Flatten every training window into slot-major, field-ordered cells."""
    rows: list[list[int]] = []
    for window in job['train']:
        flat: list[int] = []
        for row in window:
            flat.extend(int(value) for value in row)
        rows.append(flat)
    return rows


def column_vectors(rows: Sequence[Sequence[int]], columns: Sequence[str]) -> dict[str, np.ndarray]:
    """Dense columns for a list of flattened windows."""
    length = len(rows)
    vectors: dict[str, np.ndarray] = {}
    for index, name in enumerate(columns):
        vectors[name] = np.fromiter((row[index] for row in rows), dtype=np.int64, count=length)
    return vectors


def decode_queries(
    job: Mapping[str, Any],
    active_clauses: Sequence[Sequence[int]],
    universe: Universe,
    universe_true: Sequence[np.ndarray],
) -> list[dict]:
    """Answer every decoding query against the active theory."""
    theory = np.ones(universe.size, dtype=bool)
    for clause in active_clauses:
        satisfied = np.zeros(universe.size, dtype=bool)
        for predicate_id in clause:
            satisfied |= universe_true[predicate_id]
        theory &= satisfied

    answers: list[dict] = []
    for query in job.get('queries', []):
        mask = theory
        for binding in query.get('fixed') or []:
            cell = universe.position(binding['ref'])
            mask = mask & (universe.values[cell] == int(binding['value']))
        prefix = query.get('prefix', '')
        target_cell = universe.position(query['target'])
        domain = universe.field_domain(query['target'][1])
        candidates = [index for index, value in enumerate(domain) if str(value).startswith(prefix)]
        if candidates:
            lookup = np.zeros(len(domain), dtype=bool)
            lookup[candidates] = True
            mask = mask & lookup[universe.positions[target_cell]]
        else:
            mask = np.zeros(universe.size, dtype=bool)
        hits = np.flatnonzero(mask)
        count = int(hits.size)
        tokens: list[str] = []
        if count:
            seen: set[str] = set()
            ends = False
            for position in np.unique(universe.positions[target_cell][hits]):
                spelling = str(domain[int(position)])
                if len(spelling) == len(prefix):
                    ends = True
                else:
                    seen.add(spelling[len(prefix)])
            tokens = [digit for digit in DIGITS if digit in seen]
            if ends:
                tokens.append('END')
        answers.append({
            'count': count,
            'tokens': tokens,
            'witness': int(hits[0]) if count else None,
        })
    return answers


def compile_job(job: Mapping[str, Any]) -> dict:
    """Compile one job into its rules, active theory and decoding answers."""
    schema = WindowSchema(job)
    predicates = schema.predicates()
    width = int(job['width'])

    rows = flatten_windows(job)
    train_columns = column_vectors(rows, schema.columns)
    train_true = [
        evaluate_formula_vectors(predicate.formula, train_columns, len(rows))
        for predicate in predicates
    ]

    universe = Universe(job)
    universe_columns = {name: universe.values[index] for index, name in enumerate(schema.columns)}
    universe_true = [
        evaluate_formula_vectors(predicate.formula, universe_columns, universe.size)
        for predicate in predicates
    ]

    rules = enumerate_clauses(train_true, universe_true, width)

    approved = {tuple(sorted(int(value) for value in clause)) for clause in job.get('approved') or []}
    active = [rule['clause'] for rule in rules if tuple(rule['clause']) in approved]

    answers = decode_queries(job, active, universe, universe_true)
    return {'rules': rules, 'active': active, 'answers': answers}
